def transform(grid):
    # The repeated L-shaped triomino is colored 1 in one instance and 6 in the other;
    # standardize the color-1 copy to the dominant matching color 6.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(y+dy,x+dx)
            if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==1 and q not in seen:
              seen.add(q); stack.append(q)
        if len(comp)==3:
          rs=[y for y,x in comp]; cs=[x for y,x in comp]
          norm={(y-min(rs),x-min(cs)) for y,x in comp}
          if norm=={(0,0),(0,1),(1,1)}:
            for y,x in comp: out[y][x]=6
    return out
